create table if not exists public.treasure_box_stories (id uuid primary key default gen_random_uuid(),physical_box_id uuid not null unique references public.physical_treasure_boxes(id) on delete cascade,cache_id uuid references public.caches(id) on delete cascade,creator_id uuid not null references auth.users(id) on delete cascade,title text not null default '',summary text,status text not null default 'draft' check(status in ('draft','ready','published')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.treasure_box_story_chapters (id uuid primary key default gen_random_uuid(),story_id uuid not null references public.treasure_box_stories(id) on delete cascade,chapter_number integer not null check(chapter_number>0),title text,body text not null default '',image_path text,image_prompt text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(story_id,chapter_number));
alter table public.treasure_box_stories enable row level security; alter table public.treasure_box_story_chapters enable row level security;
create policy "Creators manage Treasure Box stories" on public.treasure_box_stories for all to authenticated using(creator_id=auth.uid()) with check(creator_id=auth.uid());
create policy "Creators manage Treasure Box story chapters" on public.treasure_box_story_chapters for all to authenticated using(exists(select 1 from public.treasure_box_stories s where s.id=story_id and s.creator_id=auth.uid())) with check(exists(select 1 from public.treasure_box_stories s where s.id=story_id and s.creator_id=auth.uid()));
create policy "Published Treasure Box stories readable" on public.treasure_box_stories for select to authenticated using(status='published');
create policy "Published Treasure Box story chapters readable" on public.treasure_box_story_chapters for select to authenticated using(exists(select 1 from public.treasure_box_stories s where s.id=story_id and s.status='published'));
create or replace function public.get_or_create_claimed_treasure_box_story(p_nfc_public_token uuid) returns table(story_id uuid,title text,summary text,status text) language plpgsql security definer set search_path='' as $$ declare v_box public.physical_treasure_boxes%rowtype; v_story public.treasure_box_stories%rowtype; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select ptb.* into v_box from public.physical_treasure_boxes ptb where ptb.nfc_public_token=p_nfc_public_token and ptb.owner_id=auth.uid() limit 1; if v_box.id is null then raise exception 'Treasure Box not found or not owned by you'; end if; if not ('digital_story'=any(v_box.content_options)) then raise exception 'Digital Story is not selected for this Treasure Box'; end if; select s.* into v_story from public.treasure_box_stories s where s.physical_box_id=v_box.id limit 1; if v_story.id is null then insert into public.treasure_box_stories(physical_box_id,cache_id,creator_id,title,status) values(v_box.id,v_box.cache_id,auth.uid(),'','draft') returning * into v_story; end if; return query select v_story.id,v_story.title,v_story.summary,v_story.status; end; $$;
create or replace function public.get_claimed_treasure_box_story_chapters(p_story_id uuid) returns table(chapter_id uuid,chapter_number integer,title text,body text,image_path text,image_prompt text) language sql stable security definer set search_path='' as $$ select c.id,c.chapter_number,c.title,c.body,c.image_path,c.image_prompt from public.treasure_box_story_chapters c join public.treasure_box_stories s on s.id=c.story_id where c.story_id=p_story_id and s.creator_id=auth.uid() order by c.chapter_number; $$;
create or replace function public.save_claimed_treasure_box_story(p_story_id uuid,p_title text,p_summary text) returns boolean language plpgsql security definer set search_path='' as $$ begin update public.treasure_box_stories s set title=trim(coalesce(p_title,'')),summary=nullif(trim(coalesce(p_summary,'')),''),updated_at=now() where s.id=p_story_id and s.creator_id=auth.uid(); if not found then raise exception 'Story not found'; end if; return true; end; $$;
create or replace function public.save_claimed_treasure_box_story_chapter(p_story_id uuid,p_chapter_id uuid,p_chapter_number integer,p_title text,p_body text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if not exists(select 1 from public.treasure_box_stories s where s.id=p_story_id and s.creator_id=auth.uid()) then raise exception 'Story not found'; end if; if p_chapter_number<1 then raise exception 'Chapter number must be at least 1'; end if; if p_chapter_id is null then insert into public.treasure_box_story_chapters(story_id,chapter_number,title,body) values(p_story_id,p_chapter_number,nullif(trim(coalesce(p_title,'')),''),coalesce(p_body,'')) returning id into v_id; else update public.treasure_box_story_chapters c set chapter_number=p_chapter_number,title=nullif(trim(coalesce(p_title,'')),''),body=coalesce(p_body,''),updated_at=now() where c.id=p_chapter_id and c.story_id=p_story_id returning c.id into v_id; if v_id is null then raise exception 'Chapter not found'; end if; end if; return v_id; end; $$;
create or replace function public.delete_claimed_treasure_box_story_chapter(p_story_id uuid,p_chapter_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ begin delete from public.treasure_box_story_chapters c using public.treasure_box_stories s where c.id=p_chapter_id and c.story_id=p_story_id and s.id=c.story_id and s.creator_id=auth.uid(); return found; end; $$;
revoke all on function public.get_or_create_claimed_treasure_box_story(uuid) from public; grant execute on function public.get_or_create_claimed_treasure_box_story(uuid) to authenticated;
revoke all on function public.get_claimed_treasure_box_story_chapters(uuid) from public; grant execute on function public.get_claimed_treasure_box_story_chapters(uuid) to authenticated;
revoke all on function public.save_claimed_treasure_box_story(uuid,text,text) from public; grant execute on function public.save_claimed_treasure_box_story(uuid,text,text) to authenticated;
revoke all on function public.save_claimed_treasure_box_story_chapter(uuid,uuid,integer,text,text) from public; grant execute on function public.save_claimed_treasure_box_story_chapter(uuid,uuid,integer,text,text) to authenticated;
revoke all on function public.delete_claimed_treasure_box_story_chapter(uuid,uuid) from public; grant execute on function public.delete_claimed_treasure_box_story_chapter(uuid,uuid) to authenticated;